mapper.select:
select t.machine_mac,t.machine_mac machineMac,t.impl_bean,t.impl_bean implBean,t.machine_id,t.machine_id
machineId,t.machine_code,t.machine_code machineCode,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name
machineName,t.machine_ip,t.machine_ip machineIp,t.create_time createTime,smf.factory_name implBeanName
from parking_space_machine t
LEFT JOIN space_machine_factory smf on t.impl_bean = smf.factory_id
where 1 =1

    and t.machine_mac= #{machineMac}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update parking_space_machine t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.machine_mac= #{machineMac}


    , t.impl_bean= #{implBean}


    , t.machine_code= #{machineCode}


    , t.community_id= #{communityId}


    , t.machine_name= #{machineName}


    , t.machine_ip= #{machineIp}

where 1=1

    and t.machine_id= #{machineId}

